const result = $input.first().json;
if (result.code !== 0) throw new Error('VPS package update failed. Inspect the SSH node output.');
const markers = String(result.stdout || '').match(/^N8N_REBOOT_REQUIRED=([01])$/gm) || [];
if (markers.length !== 1) throw new Error('Missing or ambiguous reboot check result.');
const name = $('VPS display name').first().json.vps_name;
if (typeof name !== 'string' || !name.trim() || name.length > 100 || /[\r\n\x00-\x1f]/.test(name)) throw new Error('Set a valid VPS display name.');
return [{json: {maintenance_version: 1, vps_name: name, reboot_required: markers[0].endsWith('1'), update_status: 'success'}}];
